import{_ as e,C as n,c as a,o,a1 as A,G as B}from"./chunks/framework.C3Hmo1as.js";const h=JSON.parse('{"title":"智能体架构演进","description":"破局“Skill 迷思”：从 LangChain、LangGraph 到 Deep Agents 的智能体架构演进","frontmatter":{"title":"智能体架构演进","description":"破局“Skill 迷思”：从 LangChain、LangGraph 到 Deep Agents 的智能体架构演进","date":"2026-10-01T00:00:00.000Z","tags":["LangChain","LangGraph","Deep Agents","Skill"]},"headers":[],"relativePath":"ai/langchain-langgraph-deep-agents-evolution.md","filePath":"ai/langchain-langgraph-deep-agents-evolution.md"}'),r={name:"ai/langchain-langgraph-deep-agents-evolution.md"};function s(g,E,l,i,C,d){const t=n("Mermaid");return o(),a("div",null,[E[0]||(E[0]=A('<p>在探讨 AI Agent（智能体）开发框架时，我们经常会听到这样一种总结：</p><blockquote><p>“LangChain、LangGraph 和 Deep Agents 同属一家公司。其中，<strong>LangChain</strong> 是最早期的链式任务编排框架；<strong>LangGraph</strong> 在其基础上拓展成了网状或图状的编排框架；而 <strong>Deep Agents</strong> 则是更现代的通用智能体，核心在于它采用了 <strong>Agent + Skill（技能）</strong> 的模式。”</p></blockquote><p>这段话前半部分对演进脉络的描述非常直观，但后半句却很容易引发一个深层的技术疑问：</p><p><strong>“现代 Agent”与“非现代 Agent”的分水岭，真的只是能不能使用 Skill 吗？</strong></p><p>如果仅仅是挂载一个 Skill，LangChain 和 LangGraph 难道就做不到吗？在工程实现上，给大模型动态塞一段操作指南（Skill）并不是什么高不可攀的黑科技，它显然不足以成为一个“划时代”的架构标准。</p><p>那么，究竟是什么底层机制，真正划开了早期智能体（Shallow Agents）与现代深层智能体（Deep Agents）的时代鸿沟？</p><h2 id="一、-厘清三者关系-不是-祖孙三代替代-而是-三层调用栈" tabindex="-1">一、 厘清三者关系：不是“祖孙三代替代”，而是“三层调用栈” <a class="header-anchor" href="#一、-厘清三者关系-不是-祖孙三代替代-而是-三层调用栈" aria-label="Permalink to &quot;一、 厘清三者关系：不是“祖孙三代替代”，而是“三层调用栈”&quot;">​</a></h2><p>很多初学者容易把 LangChain、LangGraph 和 Deep Agents 误解为“互相淘汰的三代同类产品”。实际上，它们根本不在同一个抽象层级上，而是<strong>自下而上的三层技术栈关系</strong>。</p><p>我们可以通过下面这张架构分层图来理解它们各自的生态位：</p>',9)),B(t,{code:"graph%20BT%0A%20%20%20%20subgraph%20L1%20%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%EF%BC%9A%E7%BB%84%E4%BB%B6%E4%B8%8E%E6%8E%A5%E5%8F%A3%E6%8A%BD%E8%B1%A1%E5%B1%82%20(LangChain)%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20LLM%5B%22%E7%BB%9F%E4%B8%80%E6%A8%A1%E5%9E%8B%E6%8E%A5%E5%8F%A3%20(ChatModels)%22%5D%20---%20Prompt%5B%22%E6%8F%90%E7%A4%BA%E8%AF%8D%E6%A8%A1%E6%9D%BF%20(Prompts)%22%5D%20---%20Tool%5B%22%E5%B7%A5%E5%85%B7%E5%AE%9A%E4%B9%89%E8%A7%84%E8%8C%83%20(Tools)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20L2%20%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%EF%BC%9A%E5%BA%95%E5%B1%82%E5%9B%BE%E7%8A%B6%E6%80%81%E6%9C%BA%E8%BF%90%E8%A1%8C%E6%97%B6%20(LangGraph)%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20State%5B%22%E6%8C%81%E4%B9%85%E5%8C%96%E7%8A%B6%E6%80%81%20(State)%22%5D%20--%3E%20Cycle%5B%22%E5%BE%AA%E7%8E%AF%E4%B8%8E%E5%88%86%E6%94%AF%E6%8E%A7%E5%88%B6%20(Cycles)%22%5D%20--%3E%20HIL%5B%22%E6%96%AD%E7%82%B9%E6%81%A2%E5%A4%8D%E4%B8%8E%E4%BA%BA%E5%9C%A8%E5%9B%9E%E8%B7%AF%20(Checkpointer)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20L3%20%5B%22%E7%AC%AC%E4%B8%89%E5%B1%82%EF%BC%9A%E7%8E%B0%E4%BB%A3%E6%99%BA%E8%83%BD%E4%BD%93%E8%BF%90%E8%A1%8C%E5%AE%B9%E5%99%A8%20(Deep%20Agents)%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20Plan%5B%22%E6%98%BE%E5%BC%8F%E8%A7%84%E5%88%92%E5%99%A8%20(write_todos)%22%5D%20---%20VFS%5B%22%E8%99%9A%E6%8B%9F%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%20(Virtual%20FS)%22%5D%20---%20Sub%5B%22%E5%AD%90%E6%99%BA%E8%83%BD%E4%BD%93%E9%9A%94%E7%A6%BB%20(Subagents)%22%5D%20---%20Skill%5B%22%E6%B8%90%E8%BF%9B%E5%BC%8F%E6%8A%80%E8%83%BD%E5%BA%93%20(Skills)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20L1%20%3D%3D%3E%7C%22%E6%8F%90%E4%BE%9B%E5%9F%BA%E7%A1%80%E5%8E%9F%E5%AD%90%E7%BB%84%E4%BB%B6%22%7C%20L2%0A%20%20%20%20L2%20%3D%3D%3E%7C%22%E6%8F%90%E4%BE%9B%E7%8A%B6%E6%80%81%E6%9C%BA%E4%B8%8E%E5%BE%AA%E7%8E%AF%E5%8A%A8%E5%8A%9B%E5%BA%95%E5%BA%A7%22%7C%20L3%0A"}),E[1]||(E[1]=A('<p>为了更清晰地对比，我们可以用一个造车的架构比喻来总结：</p><table tabindex="0"><thead><tr><th style="text-align:left;">框架名称</th><th style="text-align:left;">核心生态位</th><th style="text-align:left;">解决的核心痛点</th><th style="text-align:left;">工业界比喻</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LangChain</strong></td><td style="text-align:left;"><strong>组件与接口抽象层</strong></td><td style="text-align:left;">抹平不同大模型（OpenAI、Claude 等）的 API 差异，提供基础组件与单向线性串联（Chains）。</td><td style="text-align:left;"><strong>标准零件库</strong><br>（螺丝、齿轮、标准化发动机接口）</td></tr><tr><td style="text-align:left;"><strong>LangGraph</strong></td><td style="text-align:left;"><strong>底层图状态机运行时（Runtime）</strong></td><td style="text-align:left;">引入“循环（Cycles）”、“全局状态持久化”和“人在回路”，让工作流可以回退、重试、循环推理。</td><td style="text-align:left;"><strong>可编程发动机与底盘</strong><br>（提供循环动力与状态控制底座）</td></tr><tr><td style="text-align:left;"><strong>Deep Agents</strong></td><td style="text-align:left;"><strong>开箱即用的智能体容器（Agent Harness）</strong></td><td style="text-align:left;"><strong>构建在 LangGraph 之上</strong>，把 Claude Code、Manus 等现代产品的架构最佳实践固化为标准运行环境。</td><td style="text-align:left;"><strong>带自动驾驶系统的整车</strong><br>（直接拿来跑长程复杂任务）</td></tr></tbody></table><p>简言之：<strong>Deep Agents 底层依然是用 LangGraph 驱动的，而节点里的模型调用和工具封装依然依赖 LangChain 的基础抽象。</strong> 它们是层层递进的封装，而非彼此推翻。</p><h2 id="二、-破除迷思-为什么-用不用-skill-不是核心壁垒" tabindex="-1">二、 破除迷思：为什么“用不用 Skill”不是核心壁垒？ <a class="header-anchor" href="#二、-破除迷思-为什么-用不用-skill-不是核心壁垒" aria-label="Permalink to &quot;二、 破除迷思：为什么“用不用 Skill”不是核心壁垒？&quot;">​</a></h2><p>要回答为什么“Skill”不足以成为划时代的标准，我们先要看清 Agent 语境下的 <strong>Tool（工具）</strong> 和 <strong>Skill（技能）</strong> 到底有什么区别。</p><ul><li><strong>Tool（工具）</strong>：本质上是一个冷冰冰的<strong>函数接口</strong>（例如 <code>execute_sql()</code> 或 <code>read_file()</code>）。模型只知道函数的参数签名，但在面对复杂业务时，它往往不知道“先调哪个、后调哪个、遇到报错该如何降级处理”。</li><li><strong>Skill（技能）</strong>：是对 Tool 与领域知识的工程化封装。它是一套<strong>按需动态加载的“领域 SOP 手册（通常是一个 <code>SKILL.md</code>）+ 专属脚本工具集 + 少量示例（Few-shot）”</strong>。只有当 Agent 识别到特定意图时，才将这套 SOP 渐进式披露（Progressive Disclosure）到上下文中，避免一开始就把几万字的说明书塞爆上下文窗口。</li></ul><h3 id="langchain-和-langgraph-不能用-skill-吗" tabindex="-1">LangChain 和 LangGraph 不能用 Skill 吗？ <a class="header-anchor" href="#langchain-和-langgraph-不能用-skill-吗" aria-label="Permalink to &quot;LangChain 和 LangGraph 不能用 Skill 吗？&quot;">​</a></h3><p><strong>完全能用，而且实现起来一点都不难。</strong></p><p>在纯 LangGraph 甚至早期的 LangChain 中，你只需要写一个几行代码的路由节点或读取工具：当模型判定需要处理某类任务时，动态去磁盘读取一段 Markdown 格式的指令文本，追加到当前的 <code>SystemMessage</code> 或状态列表中，就手搓出了一套一模一样的 Skill 机制。</p><p>Deep Agents 所做的，只是把这套“按需读取 <code>SKILL.md</code>”的机制标准化、内置化了。因此，<strong>把“拥有 Skill”当成现代 Agent 的核心标志，其实是把一个表层的应用规范，误当成了底层的架构革命。</strong></p><h2 id="三、-真正的划时代分水岭-面向长程任务的-上下文工程" tabindex="-1">三、 真正的划时代分水岭：面向长程任务的“上下文工程” <a class="header-anchor" href="#三、-真正的划时代分水岭-面向长程任务的-上下文工程" aria-label="Permalink to &quot;三、 真正的划时代分水岭：面向长程任务的“上下文工程”&quot;">​</a></h2><p>既然 Skill 只是表象，那么真正让 LangChain / 基础 LangGraph 停留在“早期/基础设施”阶段，而让 Deep Agents 跨入“现代智能体”行列的<strong>划时代标准</strong>究竟是什么？</p><p>答案是：<strong>面向长程复杂任务（Long-Horizon Tasks）的“上下文工程（Context Engineering）与自治容器架构（Agent Harness）”</strong>。</p><h3 id="早期-agent-shallow-agents-为什么会崩溃" tabindex="-1">早期 Agent（Shallow Agents）为什么会崩溃？ <a class="header-anchor" href="#早期-agent-shallow-agents-为什么会崩溃" aria-label="Permalink to &quot;早期 Agent（Shallow Agents）为什么会崩溃？&quot;">​</a></h3><p>早期的 Agent 本质上是“一个 LLM 在循环里不断调 Tool（即基础 ReAct 循环）”。这种架构在执行 3～5 步的简单任务（比如查个天气再发封邮件）时表现得很惊艳；但一旦面对需要连续执行 50 步以上的长程任务（比如重构一个大型代码库、撰写一份深度行业研报），就会遭遇三大致命瓶颈：</p><ol><li><strong>上下文爆炸（Context Bloat）</strong>：读取了十几个文件、跑了几次搜索后，海量的原始返回结果和报错日志迅速塞满上下文窗口。</li><li><strong>注意力溃散（Attention Drift）</strong>：在几万 Token 的历史垃圾信息干扰下，大模型开始顾此失彼，推理质量断崖式下降。</li><li><strong>目标迷失（Lost in the Middle）</strong>：执行到第 30 步时，模型已经彻底忘了第 1 步设定的全局规划。</li></ol>',16)),B(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20Shallow%20%5B%22%E6%97%A9%E6%9C%9F%E6%B5%85%E5%B1%82%E6%99%BA%E8%83%BD%E4%BD%93%20(Shallow%20Agent)%20%E7%9A%84%E5%B4%A9%E6%BA%83%E9%93%BE%E8%B7%AF%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20S1%5B%22%E7%AC%AC%201%20%E6%AD%A5%EF%BC%9A%E6%8E%A5%E6%94%B6%E5%A4%8D%E6%9D%82%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20S2%5B%22%E7%AC%AC%2010%20%E6%AD%A5%EF%BC%9A%E8%BF%9E%E7%BB%AD%E8%B0%83%E7%94%A8%E5%B7%A5%E5%85%B7%3Cbr%2F%3E%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE%E5%85%A8%E9%83%A8%E5%A0%86%E5%85%A5%E5%AF%B9%E8%AF%9D%E5%8E%86%E5%8F%B2%22%5D%0A%20%20%20%20%20%20%20%20S2%20--%3E%20S3%5B%22%E7%AC%AC%2025%20%E6%AD%A5%EF%BC%9A%E4%B8%8A%E4%B8%8B%E6%96%87%E7%AA%97%E5%8F%A3%E8%A2%AB%E6%92%91%E7%88%86%3Cbr%2F%3E%E6%9C%89%E6%95%88%E4%BF%A1%E6%81%AF%E8%A2%AB%E5%99%AA%E9%9F%B3%E6%B7%B9%E6%B2%A1%22%5D%0A%20%20%20%20%20%20%20%20S3%20--%3E%20S4%5B%22%E7%AC%AC%2040%20%E6%AD%A5%EF%BC%9A%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%8F%91%E6%95%A3%3Cbr%2F%3E%E5%BD%BB%E5%BA%95%E9%81%97%E5%BF%98%E5%88%9D%E5%A7%8B%E7%9B%AE%E6%A0%87%EF%BC%8C%E4%BB%BB%E5%8A%A1%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20%20%20end%0A%20%20%20%20style%20S4%20fill%3A%23ffcccc%2Cstroke%3A%23cc0000%2Ccolor%3A%23990000%0A"}),E[2]||(E[2]=A('<p>为了彻底解决长程任务的崩溃问题，Deep Agents 吸收了以 Claude Code 和 Manus 为代表的现代 Agent 架构精髓，引入了<strong>四大核心支柱</strong>。这四大机制，才是真正的“划时代标准”：</p><hr><h3 id="支柱-1-任务隔离机制——动态派生子智能体-subagents-context-quarantine" tabindex="-1">支柱 1：任务隔离机制——动态派生子智能体（Subagents &amp; Context Quarantine） <a class="header-anchor" href="#支柱-1-任务隔离机制——动态派生子智能体-subagents-context-quarantine" aria-label="Permalink to &quot;支柱 1：任务隔离机制——动态派生子智能体（Subagents &amp; Context Quarantine）&quot;">​</a></h3><p>在非现代 Agent 架构中，主 Agent 既当爹又当妈，自己去读 20 个文件、跑 10 次搜索，中间产生的所有过程噪音全部污染在主对话历史里。</p><p>而在现代 Deep Agents 中，主 Agent 扮演的是**“总架构师/调度员”<strong>。当遇到繁琐的脏活累活（比如在几百个代码文件中排查某个函数的调用链）时，主 Agent 会通过内置的 <code>task</code> 工具，动态派生出一个生命周期极短的</strong>子智能体（Subagent）**。</p>',5)),B(t,{code:"sequenceDiagram%0A%20%20%20%20participant%20User%20as%20%E7%94%A8%E6%88%B7%0A%20%20%20%20participant%20Main%20as%20%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%20(Main%20Agent)%3Cbr%2F%3E%E3%80%90%E4%BF%9D%E6%8C%81%E4%B8%8A%E4%B8%8B%E6%96%87%E5%B9%B2%E5%87%80%E3%80%91%0A%20%20%20%20participant%20Sub%20as%20%E5%AD%90%E6%99%BA%E8%83%BD%E4%BD%93%E6%B2%99%E7%AE%B1%20(Subagent)%3Cbr%2F%3E%E3%80%90%E7%8B%AC%E7%AB%8B%E4%B8%8A%E4%B8%8B%E6%96%87%E7%AA%97%E5%8F%A3%E3%80%91%0A%20%20%20%20participant%20Tools%20as%20%E5%A4%96%E9%83%A8%E5%B7%A5%E5%85%B7%20%2F%20%E4%BB%A3%E7%A0%81%E5%BA%93%0A%0A%20%20%20%20User-%3E%3EMain%3A%20%E8%AF%B7%E5%88%86%E6%9E%90%E6%95%B4%E4%B8%AA%E9%A1%B9%E7%9B%AE%E7%9A%84%E9%89%B4%E6%9D%83%E6%BC%8F%E6%B4%9E%E5%B9%B6%E4%BF%AE%E5%A4%8D%0A%20%20%20%20Note%20over%20Main%3A%20%E6%9B%B4%E6%96%B0%20Todo%20%E6%B8%85%E5%8D%95%EF%BC%8C%E5%86%B3%E5%AE%9A%E6%B4%BE%E7%94%9F%E5%AD%90%E4%BB%BB%E5%8A%A1%0A%20%20%20%20Main-%3E%3ESub%3A%20%E6%B4%BE%E7%94%9F%20task(%22%E6%8E%92%E6%9F%A5%E6%89%80%E6%9C%89%20auth%20%E7%9B%B8%E5%85%B3%E6%96%87%E4%BB%B6%E7%9A%84%E6%BC%8F%E6%B4%9E%22)%0A%20%20%20%20%0A%20%20%20%20rect%20rgb(240%2C%20248%2C%20255)%0A%20%20%20%20%20%20%20%20Note%20over%20Sub%2CTools%3A%20%E4%B8%8A%E4%B8%8B%E6%96%87%E9%9A%94%E7%A6%BB%E5%8C%BA%20(Context%20Quarantine)%0A%20%20%20%20%20%20%20%20Sub-%3E%3ETools%3A%20grep%20%E6%90%9C%E7%B4%A2%2050%20%E4%B8%AA%E6%96%87%E4%BB%B6%20(%E6%B6%88%E8%80%97%2030%2C000%20Tokens)%0A%20%20%20%20%20%20%20%20Tools--%3E%3ESub%3A%20%E8%BF%94%E5%9B%9E%E6%B5%B7%E9%87%8F%E4%BB%A3%E7%A0%81%E7%89%87%E6%AE%B5%E4%B8%8E%E6%8A%A5%E9%94%99%E6%97%A5%E5%BF%97%0A%20%20%20%20%20%20%20%20Sub-%3E%3ETools%3A%20%E9%80%90%E4%B8%80%E9%98%85%E8%AF%BB%E6%A0%B8%E5%BF%83%E6%96%87%E4%BB%B6%E5%B9%B6%E4%BA%A4%E5%8F%89%E9%AA%8C%E8%AF%81%0A%20%20%20%20%20%20%20%20Tools--%3E%3ESub%3A%20%E8%BF%94%E5%9B%9E%E8%AF%A6%E7%BB%86%E4%BB%A3%E7%A0%81%E5%86%85%E5%AE%B9%0A%20%20%20%20end%0A%0A%20%20%20%20Sub--%3E%3EMain%3A%20%E9%94%80%E6%AF%81%E4%B8%AD%E9%97%B4%E8%BF%87%E7%A8%8B%EF%BC%8C%E4%BB%85%E8%BF%94%E5%9B%9E%20300%20%E5%AD%97%E6%8E%92%E6%9F%A5%E7%BB%93%E8%AE%BA%0A%20%20%20%20Note%20over%20Main%3A%20%E4%B8%BB%E4%B8%8A%E4%B8%8B%E6%96%87%E4%BB%85%E5%A2%9E%E5%8A%A0%20300%20%E5%AD%97%EF%BC%81%3Cbr%2F%3E%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%E4%B8%8B%E4%B8%80%E6%AD%A5%E4%BF%AE%E5%A4%8D%E8%A7%84%E5%88%92%0A%20%20%20%20Main-%3E%3EUser%3A%20%E6%BC%8F%E6%B4%9E%E6%8E%92%E6%9F%A5%E4%B8%8E%E4%BF%AE%E5%A4%8D%E5%AE%8C%E6%88%90%EF%BC%8C%E6%B1%87%E6%80%BB%E6%8A%A5%E5%91%8A%E5%A6%82%E4%B8%8B...%0A"}),E[3]||(E[3]=A('<p>子智能体在自己独立的内存沙箱里消耗掉几万 Token 完成排查后，直接销毁自身与中间过程，<strong>只把最终提炼出的几百字精准结论返回给主 Agent</strong>。这种<strong>“上下文隔离防火墙（Context Quarantine）”</strong>机制，让主 Agent 的大脑永远保持清爽与清醒。</p><hr><h3 id="支柱-2-外存卸载机制——内置虚拟文件系统-virtual-file-system" tabindex="-1">支柱 2：外存卸载机制——内置虚拟文件系统（Virtual File System） <a class="header-anchor" href="#支柱-2-外存卸载机制——内置虚拟文件系统-virtual-file-system" aria-label="Permalink to &quot;支柱 2：外存卸载机制——内置虚拟文件系统（Virtual File System）&quot;">​</a></h3><p>早期 Agent 把所有的中间产物、长文本全都放在对话消息列表（<code>Messages State</code>）里传来传去。</p><p>现代 Deep Agents 则引入了计算机体系结构的思想：<strong>把大模型的上下文窗口当成极其宝贵的 CPU 一级缓存（L1 Cache），同时为 Agent 挂载一套内置的虚拟文件系统（配备 <code>ls</code>、<code>read_file</code>、<code>write_file</code>、<code>edit_file</code>、<code>grep</code> 等标准工具）作为“内存与硬盘”。</strong></p><ul><li><strong>大结果自动卸载</strong>：当某个工具返回了超长文本时，系统不再将其直接塞进对话流，而是转存到虚拟文件系统中，只给模型返回一个文件路径和简短摘要，让模型按需用 <code>read_file</code> 或 <code>grep</code> 分页查看。</li><li><strong>多智能体协同黑板</strong>：主智能体与子智能体之间不需要通过冗长的对话传递数据，直接读写虚拟文件系统中的同一份文件即可完成状态共享。</li><li><strong>上下文自动压缩</strong>：当历史消息逼近阈值时，中间件会自动将早期对话归档写入文件，并用高密度摘要替换原对话流。</li></ul><hr><h3 id="支柱-3-注意力锚定机制——显式状态规划工具-write-todos" tabindex="-1">支柱 3：注意力锚定机制——显式状态规划工具（<code>write_todos</code>） <a class="header-anchor" href="#支柱-3-注意力锚定机制——显式状态规划工具-write-todos" aria-label="Permalink to &quot;支柱 3：注意力锚定机制——显式状态规划工具（`write_todos`）&quot;">​</a></h3><p>早期 Agent 只靠提示词里的“Let&#39;s think step by step（一步步思考）”来做规划，没有持久化的任务账本，跑上几十步必然偏离航道。</p><p>Deep Agents 内置了一个强制性的 <code>write_todos</code> 规划工具。非常有趣的是，LangChain 官方团队曾坦承：<strong>这个工具在底层代码实现上几乎是个“空操作（No-op）”</strong>——它不调用任何外部 API，仅仅是在状态机里更新一张结构化的待办清单（包含 <code>pending</code>、<code>in_progress</code>、<code>completed</code> 状态）。</p><p>但这恰恰是一种极其高明的<strong>上下文工程策略</strong>：通过强制模型在每个关键节点调用该工具来重写或勾选任务清单，系统不断地将“全局目标与当前进度”刷新到上下文窗口的最末端（即模型注意力最集中的位置），从而在长达上百步的循环中牢牢锁住模型的注意力锚点。</p><hr><h3 id="支柱-4-编排范式的转移——从-手写控制流-到-自主环境容器-agent-harness" tabindex="-1">支柱 4：编排范式的转移——从“手写控制流”到“自主环境容器（Agent Harness）” <a class="header-anchor" href="#支柱-4-编排范式的转移——从-手写控制流-到-自主环境容器-agent-harness" aria-label="Permalink to &quot;支柱 4：编排范式的转移——从“手写控制流”到“自主环境容器（Agent Harness）”&quot;">​</a></h3><p>这是开发体验上最本质的跨越：</p><ul><li><strong>传统 LangChain / LangGraph 开发（手写控制流）</strong>：程序员像画流程图一样，在代码里硬编码：“节点 A 调搜索 -&gt; 走条件边判断 -&gt; 若失败走节点 B 重试 -&gt; 若成功走节点 C 总结”。<strong>控制流是由人类程序员预先写死的。</strong></li><li><strong>现代 Deep Agents 开发（Agent Harness 容器）</strong>：框架直接提供一个像操作系统一样的“重型容器”——里面已经预置了经过严密调优的工业级长系统提示词、虚拟文件系统、子智能体派生器、规划账本以及按需加载的 Skills 规范。程序员不再去硬编码“第几步走哪个分支”，而是规定好工具边界、挂载好领域 Skill，让大模型在容器内自主规划、自己读写文件、动态派发子任务。</li></ul><h2 id="四、-三代架构全景演进对比与选型指南" tabindex="-1">四、 三代架构全景演进对比与选型指南 <a class="header-anchor" href="#四、-三代架构全景演进对比与选型指南" aria-label="Permalink to &quot;四、 三代架构全景演进对比与选型指南&quot;">​</a></h2><p>我们将这三者的拓扑结构放在一起，就能一目了然地看清从“链”到“图”，再到“现代深层智能体容器”的进化全貌：</p>',17)),B(t,{code:"flowchart%20TB%0A%20%20%20%20subgraph%20Stage1%20%5B%221.%20LangChain%20(%E7%BA%BF%E6%80%A7%E9%93%BE%E4%B8%8E%E5%9F%BA%E7%A1%80%E7%BB%84%E4%BB%B6)%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20A1%5B%22%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%22%5D%20--%3E%20A2%5B%22Prompt%20%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20A3%5B%22LLM%20%E6%8E%A8%E7%90%86%22%5D%20--%3E%20A4%5B%22Tool%20%E8%B0%83%E7%94%A8%22%5D%20--%3E%20A5%5B%22%E8%BE%93%E5%87%BA%E7%BB%93%E6%9E%9C%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Stage2%20%5B%222.%20LangGraph%20(%E5%BA%95%E5%B1%82%E5%9B%BE%E7%8A%B6%E6%80%81%E6%9C%BA%E8%BF%90%E8%A1%8C%E6%97%B6)%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20B1%5B%22%E5%85%A5%E5%8F%A3%E8%8A%82%E7%82%B9%22%5D%20--%3E%20B2%5B%22%E8%B7%AF%E7%94%B1%2F%E6%8E%A8%E7%90%86%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20%20%20%20%20B2%20--%3E%7C%22%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF%20A%22%7C%20B3%5B%22%E5%B7%A5%E5%85%B7%E6%89%A7%E8%A1%8C%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20%20%20%20%20B2%20--%3E%7C%22%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF%20B%22%7C%20B4%5B%22%E4%BA%BA%E5%B7%A5%E5%AE%A1%E6%89%B9%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20%20%20%20%20B3%20--%3E%7C%22%E5%BE%AA%E7%8E%AF%E5%8F%8D%E9%A6%88%20(Cycle)%22%7C%20B2%0A%20%20%20%20%20%20%20%20B4%20--%3E%20B5%5B%22%E6%8C%81%E4%B9%85%E5%8C%96%E8%BE%93%E5%87%BA%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Stage3%20%5B%223.%20Deep%20Agents%20(%E6%9E%84%E5%BB%BA%E4%BA%8E%20LangGraph%20%E4%B9%8B%E4%B8%8A%E7%9A%84%E7%8E%B0%E4%BB%A3%20Agent%20Harness)%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20C_Main%5B%22%E4%B8%BB%E5%8D%8F%E8%B0%83%E6%99%BA%E8%83%BD%E4%BD%93%20(Main%20Orchestrator)%3Cbr%2F%3E%E5%86%85%E7%BD%AE%E5%B7%A5%E4%B8%9A%E7%BA%A7%20System%20Prompt%20%E4%B8%8E%E4%B8%8A%E4%B8%8B%E6%96%87%E8%87%AA%E5%8A%A8%E6%91%98%E8%A6%81%22%5D%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20C_Main%20%3C--%3E%7C%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E9%94%9A%E5%AE%9A%22%7C%20C_Todo%5B%22%E6%98%BE%E5%BC%8F%E8%A7%84%E5%88%92%E5%99%A8%3Cbr%2F%3E(write_todos)%22%5D%0A%20%20%20%20%20%20%20%20C_Main%20%3C--%3E%7C%22%E5%A4%96%E5%AD%98%E8%AF%BB%E5%86%99%E5%8D%B8%E8%BD%BD%22%7C%20C_VFS%5B%22%E8%99%9A%E6%8B%9F%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%3Cbr%2F%3E(ls%20%2F%20read%20%2F%20write%20%2F%20edit)%22%5D%0A%20%20%20%20%20%20%20%20C_Main%20%3C--%3E%7C%22%E6%8C%89%E9%9C%80%E5%8A%A8%E6%80%81%E6%B3%A8%E5%85%A5%22%7C%20C_Skill%5B%22%E9%A2%86%E5%9F%9F%E6%8A%80%E8%83%BD%E5%BA%93%3Cbr%2F%3E(Skills%20%2F%20SKILL.md)%22%5D%0A%20%20%20%20%20%20%20%20C_Main%20--%3E%7C%22%E6%B4%BE%E7%94%9F%E9%9A%94%E7%A6%BB%E4%BB%BB%E5%8A%A1%20(task)%22%7C%20C_Sub1%5B%22%E5%AD%90%E6%99%BA%E8%83%BD%E4%BD%93%E6%B2%99%E7%AE%B1%201%3Cbr%2F%3E(%E7%8B%AC%E7%AB%8B%E4%B8%8A%E4%B8%8B%E6%96%87)%22%5D%0A%20%20%20%20%20%20%20%20C_Main%20--%3E%7C%22%E6%B4%BE%E7%94%9F%E9%9A%94%E7%A6%BB%E4%BB%BB%E5%8A%A1%20(task)%22%7C%20C_Sub2%5B%22%E5%AD%90%E6%99%BA%E8%83%BD%E4%BD%93%E6%B2%99%E7%AE%B1%202%3Cbr%2F%3E(%E7%8B%AC%E7%AB%8B%E4%B8%8A%E4%B8%8B%E6%96%87)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Stage1%20-.-%3E%7C%22%E6%BC%94%E8%BF%9B%EF%BC%9A%E5%BC%95%E5%85%A5%E5%BE%AA%E7%8E%AF%E4%B8%8E%E7%8A%B6%E6%80%81%E6%8C%81%E4%B9%85%E5%8C%96%22%7C%20Stage2%0A%20%20%20%20Stage2%20-.-%3E%7C%22%E5%B0%81%E8%A3%85%EF%BC%9A%E6%B3%A8%E5%85%A5%E9%95%BF%E7%A8%8B%E4%B8%8A%E4%B8%8B%E6%96%87%E5%B7%A5%E7%A8%8B%E8%8C%83%E5%BC%8F%22%7C%20Stage3%0A"}),E[4]||(E[4]=A('<h3 id="实战选型建议-我们该如何选择" tabindex="-1">实战选型建议：我们该如何选择？ <a class="header-anchor" href="#实战选型建议-我们该如何选择" aria-label="Permalink to &quot;实战选型建议：我们该如何选择？&quot;">​</a></h3><p>理解了三者的定位后，在实际工程项目中，我们就不必盲目追新，而是根据业务场景精准选型：</p><ol><li><strong>什么时候直接用 LangChain？</strong> 当你只需要快速实现一个简单的单步对话、基础的文档问答（RAG），或者只需要复用它现成的 Model/Tool 封装接口时，LangChain 依然是最轻量、最便捷的零件库。</li><li><strong>什么时候退回到底层手写 LangGraph？</strong> 当你的业务流程具有<strong>极强的确定性要求和严密的合规边界</strong>时（例如银行信贷审批流、固定SOP的客服退换货流程）。这类场景下，你绝对不希望大模型自由发挥，而是需要由程序员用图节点（Nodes）和条件边（Edges）把每一步状态流转死死锁住。</li><li><strong>什么时候直接上现代的 Deep Agents？</strong> 当你要构建的是<strong>开放式、长链路、高自治度的复杂智能体</strong>时（例如：自主编写并调试代码的 AI 程序员、自动搜集全网资料生成万字报告的 Deep Research 助手、复杂数据分析 Agent）。直接采用 Deep Agents 的容器架构，能帮你省去从零手搓虚拟文件系统、上下文裁剪、Todo 账本和子代理隔离沙箱的巨大工程量。</li></ol><h2 id="五、-结语" tabindex="-1">五、 结语 <a class="header-anchor" href="#五、-结语" aria-label="Permalink to &quot;五、 结语&quot;">​</a></h2><p>回到我们最初的问题：<strong>现代 Agent 与早期 Agent 的划时代分水岭到底是什么？</strong></p><p>绝不是表象上的“能不能用 Skill”，而是<strong>底层架构从“工具连接器”向“长程上下文工程容器（Agent Harness）”的范式跃迁</strong>。</p><blockquote><p>早期的框架（LangChain / 基础编排）致力于帮我们**“把大模型和外部工具连起来”<strong>；而现代的深层智能体架构（Deep Agents）则是在构建一套类似操作系统的运行时环境——它通过</strong>虚拟文件系统<strong>做外存卸载、通过</strong>动态子智能体<strong>做上下文隔离、通过</strong>显式 Todo 账本**做注意力锚定、通过 <strong>Skill 规范</strong>做领域知识的渐进式披露。</p></blockquote><p>正是这四大支柱的协同运转，才让 AI Agent 真正跨越了“玩具级 Demo”的局限，具备了连续自主执行几十上百步复杂任务而不崩溃的现代工程能力。</p>',8))])}const D=e(r,[["render",s]]);export{h as __pageData,D as default};
